from pathlib import Path
program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each source pattern consists of complete, parallel colored lines.
    # Try horizontal, down-right diagonal (r-c), and up-right diagonal (r+c).
    coords = {
        "row": lambda r, c: r,
        "down": lambda r, c: r - c,
        "up": lambda r, c: r + c,
    }
    best = None
    for name, fn in coords.items():
        groups = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    groups.setdefault(fn(r, c), []).append(v)
        good = {k: vals[0] for k, vals in groups.items()
                if len(vals) >= 2 and len(set(vals)) == 1}
        support = sum(len(groups[k]) for k in good)
        score = (support, len(good))
        if best is None or score > best[0]:
            best = (score, name, fn, good)
    _, name, fn, lines = best
    # The number of represented stripes is the motif period.
    period = len(lines)
    if period == 0:
        return [row[:] for row in grid]
    motif = {}
    for idx, color in lines.items():
        residue = idx % period
        if residue in motif and motif[residue] != color:
            # Defensive fallback: preserve the most recently observed stripe.
            pass
        motif[residue] = color
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append(motif[fn(r, c) % period])
        out.append(row)
    return out
'''
